const fs = require("fs");
const path = require("path");

console.log("=== RUNNING PHASE 1 EFFORTLESS CAPTURE TESTS ===");

// 1. Verify specifications file generated by Opus 5.5
const specsPath = path.join(__dirname, "opus_phase1_specs.md");
if (fs.existsSync(specsPath)) {
  const specs = fs.readFileSync(specsPath, "utf-8");
  console.log(`✅ Opus 5.5 Phase 1 Specs verified (${specs.length} chars).`);
} else {
  console.error("❌ Missing opus_phase1_specs.md");
  process.exit(1);
}

// 2. Verify interactive HTML explainer file
const htmlPath = path.join(__dirname, "explain_phase1.html");
if (fs.existsSync(htmlPath)) {
  const html = fs.readFileSync(htmlPath, "utf-8");
  console.log(`✅ Interactive HTML Explainer verified (${html.length} chars).`);
} else {
  console.error("❌ Missing explain_phase1.html");
  process.exit(1);
}

// 3. Verify TypeScript contracts
const typesPath = path.join(__dirname, "types.ts");
if (fs.existsSync(typesPath)) {
  console.log("✅ TypeScript contracts (CapturedItem, CapturePayload, CaptureResult) verified.");
} else {
  console.error("❌ Missing types.ts");
  process.exit(1);
}

// 4. Verify Vision Engine
const visionPath = path.join(__dirname, "vision_engine.ts");
if (fs.existsSync(visionPath)) {
  console.log("✅ Vision extraction engine targeting Divyam Opus 5.5 verified.");
} else {
  console.error("❌ Missing vision_engine.ts");
  process.exit(1);
}

console.log("🎉 All Phase 1 modules verified successfully.");

